/** Names for the icon picker in the editor. */
function glyph_names(): array
{
    return array_keys(ST_GLYPHS);
}

function glyph(string $name, string $class = 'h-6 w-6', float $stroke = 1.6): string
{
    $inner = ST_GLYPHS[$name] ?? ST_GLYPHS['cog'];
    return '<svg class="' . e($class) . '" fill="none" stroke="currentColor" stroke-width="' . $stroke
        . '" stroke-linecap="round" stroke-linejoin="round" viewBox="0 0 24 24" aria-hidden="true">' . $inner . '</svg>';
}

function step_glyph(int $i, string $stroke, string $class = 'h-10 w-10'): string
{
    $inner = ST_STEP_GLYPHS[$i % count(ST_STEP_GLYPHS)];
    return '<svg class="' . e($class) . '" viewBox="0 0 40 40" fill="none" stroke="' . e($stroke)
        . '" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' . $inner . '</svg>';
}

function qs_glyph(int $i, string $stroke, string $class = 'h-8 w-8'): string
{
    $inner = ST_QS_GLYPHS[$i % count(ST_QS_GLYPHS)];
    return '<svg class="' . e($class) . '" viewBox="0 0 40 40" fill="none" stroke="' . e($stroke)
        . '" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' . $inner . '</svg>';
}

function social_icon(string $name, string $class = 'h-4 w-4'): string
{
    $icon = ST_SOCIAL[strtolower($name)] ?? ST_SOCIAL['linkedin'];
    return '<svg class="' . e($class) . '" fill="currentColor" viewBox="' . $icon[0] . '" aria-hidden="true"><path d="' . $icon[1] . '"/></svg>';
}

function arrow_icon(string $class = 'h-4 w-4', float $stroke = 2): string
